'use strict';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=null, project=null, page='inicio', active='tema', sourceId='', editSource='', authMode='login';
const nav=[['inicio','◈','Inicio'],['docente','◫','Panel docente'],['ruta','◎','Ruta de aprendizaje'],['investigacion','▤','Mi investigación'],['biblioteca','▥','Biblioteca y citas'],['lectura','▧','Lectura crítica'],['mentor','✧','Mentor'],['portafolio','▣','Portafolio'],['exportar','↓','Exportación'],['revision','◷','Revisión docente'],['contenidos','▤','Contenidos'],['perfil','○','Mi perfil']];
let toastTimer=0;function toast(t){clearTimeout(toastTimer);$('#toast').textContent=t;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),6500)}
function clearToast(){clearTimeout(toastTimer);$('#toast').classList.remove('show')}
/* Fuente única para las tres ediciones:
   - supabaseapi.js cargado: edición en la nube (Supabase), CLOUD;
   - localapi.js cargado: edición web, datos en este navegador, WEB;
   - ninguno: edición local con el servidor Python. */
const CLOUD=!!window.InvestigaCloud, WEB=!CLOUD&&!!window.InvestigaLocal, BACKEND=window.InvestigaCloud||window.InvestigaLocal||null;
async function api(path,data){if(BACKEND){try{return await BACKEND.request(path,data)}catch(e){throw new Error(e.message||'No se pudo realizar la operación')}}let r;try{r=await fetch('/api/'+path,{method:data===undefined?'GET':'POST',headers:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)})}catch(e){throw new Error('No hay conexión con el servidor. Conserva tu borrador y vuelve a intentarlo.')}if(!r.ok){let v={};try{v=await r.json()}catch{}throw new Error(v.error||'No se pudo realizar la operación')}return r.headers.get('Content-Disposition')?r:await r.json()}
function projectApi(action='',data){return api('projects/'+project.project.id+(action?'/'+action:''),data)}
async function reload(){state=await api('state');let id=project?.project.id||sessionStorage.getItem('project');if(!state.projects.some(p=>p.id===id))id=state.projects[0]?.id;project=id?await api('projects/'+id):null;if(id)sessionStorage.setItem('project',id)}
function activityTitle(id){return state.activities.find(a=>a.id===id)?.title||id}
function latest(a){return project?.versions.find(v=>v.activity===a)}
function xp(){return project?.rewards.reduce((n,r)=>n+r.xp,0)||0}
function progress(){return Math.round((project?.rewards.length||0)/state.activities.length*100)}
function draftKey(a){return `investiga:${state.user.id}:${project.project.id}:${a}`}
function field(name,value='',type='textarea'){return `<label>${esc(name)}${type==='textarea'?`<textarea name="${esc(name)}" maxlength="12000">${esc(value)}</textarea>`:`<input name="${esc(name)}" value="${esc(value)}" type="${type}" maxlength="300">`}</label>`}
function header(title,sub,action=''){return `<div class="heading"><div><div class="eyebrow">Tu espacio de investigación</div><h1>${title}</h1><p class="muted">${sub}</p></div>${action}</div>`}
function empty(){return `<div class="card empty"><div class="icon">＋</div><h2>Tu investigación comienza aquí</h2><p class="muted">Crea un proyecto para reunir tus ideas, lecturas y evidencias.</p><button data-do="new">Crear mi primer proyecto</button></div>`}
function auth(){const reg=authMode==='register',reset=authMode==='reset',newpass=authMode==='newpass';
 const title=reg?'Crea tu cuenta':reset?'Recupera tu acceso':newpass?'Crea una contraseña nueva':'Continúa tu investigación';
 const intro=reset?(CLOUD?'Escribe el correo de tu cuenta. Te enviaremos un enlace para crear una contraseña nueva.':'Escribe tu correo, el código de recuperación que guardaste al crear la cuenta y una contraseña nueva.'):newpass?'Abriste el enlace de recuperación. Elige una contraseña nueva de al menos 10 caracteres.':'Tu portafolio, tus fuentes y tu progreso en un solo lugar.';
 const pw=(label,name)=>`<label>${label}<input type="password" name="${name}" required minlength="10" autocomplete="new-password"></label>`;
 const mail='<label>Correo electrónico<input type="email" name="email" required autocomplete="email"></label>';
 const storage=CLOUD?'en la plataforma InvestigaApp (servidor seguro de Supabase), que solo mis docentes autorizados podrán consultarlos,':WEB?'solo en este navegador (no en un servidor)':'en este equipo';
 const fields=newpass?pw('Nueva contraseña','password')+pw('Repite la nueva contraseña','confirm'):reset?(CLOUD?mail+'<p class="muted"><small>Si no llega en unos minutos, revisa la carpeta de spam. El enlace sirve una sola vez.</small></p>':`${mail}<label>Código de recuperación<input name="code" required autocomplete="off" spellcheck="false" placeholder="XXXX-XXXX-XXXX-XXXX"></label>${pw('Nueva contraseña','password')}${pw('Repite la nueva contraseña','confirm')}<p class="muted"><small>${WEB?'Si perdiste el código, en la edición web no es posible recuperar la cuenta.':'Si perdiste el código, pide a quien administra este equipo una contraseña temporal.'}</small></p>`):`${reg?field('Nombre','','text'):''}${mail}<label>Contraseña<input type="password" name="password" required minlength="10" autocomplete="${reg?'new-password':'current-password'}"></label>${reg?'<label class="check"><input type="checkbox" required>Entiendo que mis datos se guardan '+storage+' y acepto utilizar la orientación con criterio académico.</label>':''}`;
 const submit=reg?'Crear cuenta':reset?(CLOUD?'Enviarme el enlace':'Cambiar contraseña y entrar'):newpass?'Guardar contraseña y entrar':'Ingresar';
 const edition=CLOUD?'Edición en la nube · Tu progreso está disponible desde cualquier equipo':WEB?'Edición web · Tus datos permanecen en este navegador':'Edición local · Sin servicios de nube conectados';
 $('#app').innerHTML=`<div class="auth"><div class="auth-intro"><div class="brand-icon">◈</div><div class="brand">Investiga<span>App</span><small>ProfeJohn.educa</small></div><h1>Una idea.<br>Todo un camino<br>por investigar.</h1><p>Aprende, construye y mejora tu proyecto de investigación paso a paso.</p><p>◎ Rutas guiadas &nbsp; ▤ Evidencias &nbsp; ✧ Orientación</p></div><section class="auth-form"><div class="eyebrow">Bienvenido a tu siguiente descubrimiento</div><h2>${title}</h2><p class="muted">${intro}</p><form id="auth">${fields}<button class="accent">${submit}</button><p id="auth-error" role="alert" class="error"></p><p id="auth-info" role="status" class="notice" hidden></p></form>${authMode==='login'?'<button class="link" data-auth="reset">¿Olvidaste tu contraseña?</button>':''}${newpass?'':`<button class="secondary" data-auth="${reg||reset?'login':'register'}">${reg||reset?'Ya tengo una cuenta':'Crear una cuenta nueva'}</button>`}<p class="muted"><small>${edition}</small></p></section></div>`;
 document.querySelectorAll('[data-auth]').forEach(b=>b.onclick=()=>{authMode=b.dataset.auth;auth()});
 const info=text=>{$('#auth-error').textContent='';$('#auth-info').textContent=text;$('#auth-info').hidden=false};
 $('#auth').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),b=e.submitter;if(b)b.disabled=true;try{
  if((newpass||reset&&!CLOUD)&&f.get('password')!==f.get('confirm'))throw new Error('Las contraseñas nuevas no coinciden.');
  if(newpass){await api('reset-confirm',{password:f.get('password')});authMode='login';await reload();page=state.user.role==='docente'?'docente':'inicio';render();toast('Contraseña cambiada.');return}
  if(reset&&CLOUD){await api('reset',{email:f.get('email')});e.target.reset();info('Si el correo corresponde a una cuenta, te enviamos un enlace para crear una contraseña nueva. Ábrelo desde este mismo dispositivo.');return}
  const r=await api(authMode,reset?{email:f.get('email'),code:f.get('code'),password:f.get('password')}:{name:f.get('Nombre'),email:f.get('email'),password:f.get('password')});
  if(r.pendingConfirmation){authMode='login';auth();info('Cuenta creada. Te enviamos un correo de confirmación: ábrelo y luego ingresa con tu contraseña. Si no llega, revisa la carpeta de spam.');return}
  authMode='login';await reload();page=state.user.role==='docente'?'docente':'inicio';render();
  if(r.recoveryCode)showRecoveryCode(r.recoveryCode,reset?'Contraseña cambiada. Tu código anterior ya no sirve: guarda este nuevo código.':'Tu cuenta está lista. Este código te permitirá recuperar el acceso si olvidas tu contraseña.');
 }catch(err){$('#auth-error').textContent=err.message;if($('#auth-info'))$('#auth-info').hidden=true}finally{if(b)b.disabled=false}}}
function showRecoveryCode(code,message){
 const box=document.createElement('div');box.className='modal';box.setAttribute('role','dialog');box.setAttribute('aria-modal','true');box.setAttribute('aria-labelledby','rc-title');
 box.innerHTML=`<div class="card"><h2 id="rc-title">Guarda tu código de recuperación</h2><p>${esc(message)}</p><p class="recovery-code" aria-label="Código de recuperación">${esc(code)}</p><p class="muted"><small>Se muestra solo esta vez. Guárdalo fuera de la aplicación (por ejemplo, impreso o en un gestor de contraseñas). Cada código sirve una sola vez.</small></p><div class="actions"><button type="button" class="secondary" id="rc-copy">Copiar</button><button type="button" class="secondary" id="rc-download">Descargar .txt</button></div><label class="check"><input type="checkbox" id="rc-ok">Ya guardé mi código en un lugar seguro</label><div class="actions"><button type="button" class="accent" id="rc-close" disabled>Continuar</button></div></div>`;
 document.body.appendChild(box);
 box.querySelector('#rc-copy').onclick=()=>navigator.clipboard.writeText(code).then(()=>toast('Código copiado.'),()=>toast('No se pudo copiar; anótalo o descárgalo.'));
 box.querySelector('#rc-download').onclick=()=>{const url=URL.createObjectURL(new Blob([['InvestigaApp · Código de recuperación','','Cuenta: '+(state?.user.email||''),'Código: '+code,'','Úsalo en «¿Olvidaste tu contraseña?». Sirve una sola vez.'].join(String.fromCharCode(13,10))],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='InvestigaApp-codigo-recuperacion.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
 box.querySelector('#rc-ok').onchange=e=>{box.querySelector('#rc-close').disabled=!e.target.checked};
 box.querySelector('#rc-close').onclick=()=>{box.remove();render()};
 box.querySelector('#rc-copy').focus();}
function security(){const r=state.user.hasRecovery;if(CLOUD)return securityCloud();return `<div class="card" id="seguridad"><h2>Seguridad</h2><h3>Cambiar contraseña</h3><form id="password"><label>Contraseña actual<input type="password" name="current" required autocomplete="current-password"></label><label>Nueva contraseña<input type="password" name="password" required minlength="10" autocomplete="new-password"></label><label>Repite la nueva contraseña<input type="password" name="confirm" required minlength="10" autocomplete="new-password"></label><button>Cambiar contraseña</button></form><p class="muted"><small>${WEB?'Al cambiarla, la sesión de este navegador sigue abierta.':'Al cambiarla se cierran tus sesiones abiertas en otros navegadores.'}</small></p><h3>Código de recuperación</h3><p><span class="pill ${r?'done':'warn'}">${r?'Configurado':'Sin código'}</span></p><p class="muted">${r?'Si perdiste tu código o crees que otra persona lo conoce, genera uno nuevo: el anterior dejará de funcionar.':'Sin un código de recuperación no podrás entrar si olvidas tu contraseña. Genera uno ahora.'}</p><form id="recovery"><label>Confirma con tu contraseña actual<input type="password" name="current" required autocomplete="current-password"></label><button class="${r?'secondary':'accent'}">${r?'Generar un código nuevo':'Generar mi código'}</button></form>${WEB?'':'<p class="muted"><small>Si alguien pierde contraseña y código, quien administra el equipo puede asignar una contraseña temporal con <code>python backend/server.py --reset-password correo</code>.</small></p>'}</div>`}
function securityCloud(){return `<div class="card" id="seguridad"><h2>Seguridad</h2><h3>Cambiar contraseña</h3><form id="password"><label>Contraseña actual<input type="password" name="current" required autocomplete="current-password"></label><label>Nueva contraseña<input type="password" name="password" required minlength="10" autocomplete="new-password"></label><label>Repite la nueva contraseña<input type="password" name="confirm" required minlength="10" autocomplete="new-password"></label><button>Cambiar contraseña</button></form><p class="muted"><small>Si olvidas tu contraseña, usa «¿Olvidaste tu contraseña?» en la pantalla de ingreso: te enviaremos un enlace a tu correo.</small></p></div>`}
function render(){if(!state)return auth();$('#app').innerHTML=`<div class="shell"><aside><div class="brand-icon">◈</div><div class="brand">Investiga<span>App</span><small>ProfeJohn.educa</small></div><nav aria-label="Navegación principal">${nav.filter(([id])=>id!=='docente'||state.user.role==='docente').map(([id,icon,label])=>`<button data-page="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}><span>${icon}</span>${label}</button>`).join('')}</nav><div class="aside-bottom">APRENDE. INVESTIGA. TRANSFORMA.<br>${CLOUD?'Edición web · Datos seguros en la nube<br><a class="aside-link" href="../">← Sitio de InvestigaApp</a>':WEB?'Edición web · Datos en este navegador<br><a class="aside-link" href="../">← Sitio de InvestigaApp</a>':'Edición local · Arquitectura en dos capas'}</div></aside><main><div class="topbar"><div><label class="sr-only" for="project-select">Proyecto activo</label><select id="project-select"><option value="">Selecciona un proyecto</option>${state.projects.map(p=>`<option value="${p.id}" ${project?.project.id===p.id?'selected':''}>${esc(p.title)}</option>`).join('')}</select></div><div class="user"><span id="network" class="muted">● ${CLOUD?(navigator.onLine?'En línea':'Sin conexión'):WEB?(navigator.onLine?'En línea · datos locales':'Sin conexión · datos locales'):(navigator.onLine?'Local':'Sin conexión')}</span><div class="avatar">${esc(state.user.name[0].toUpperCase())}</div><small>${esc(state.user.name)}</small><button class="secondary" data-do="logout">Salir</button></div></div><div id="content"></div></main></div>`;$('#content').innerHTML=content();bind();}
function content(){if(page==='docente')return teacherPanel();if(page==='perfil')return profile();if(page==='contenidos')return contents();if(page==='ruta')return route();if(!project)return header('Bienvenido, '+esc(state.user.name.split(' ')[0]),'Dale forma a tu próxima pregunta.')+empty();switch(page){case 'inicio':return dashboard();case 'investigacion':return editor();case 'biblioteca':return library();case 'lectura':return reading();case 'mentor':return mentor();case 'portafolio':return portfolio();case 'exportar':return exports();case 'revision':return reviews();case 'contenidos':return contents()}return ''}
function dashboard(){const next=state.activities.find(a=>!project.rewards.some(r=>r.activity===a.id));return header('Hola, '+esc(state.user.name.split(' ')[0])+' 👋','Cada evidencia es un paso hacia una investigación más sólida.','<button class="secondary" data-do="new">＋ Nuevo proyecto</button>')+`${state.user.hasRecovery?'':'<div class="notice row"><span>Aún no tienes un código de recuperación. Sin él no podrás entrar si olvidas tu contraseña.</span><button class="secondary" data-page="perfil">Generarlo en Mi perfil</button></div>'}<div class="card hero"><div class="eyebrow">${esc(state.user.diagnosis?.route||'Comienza por conocerte')}</div><h2>${state.user.diagnosis?'Tu próxima misión: '+esc(next?.title||'revisar tu portafolio'):'Descubre tu punto de partida'}</h2><p>${state.user.diagnosis?'Construye una propuesta, revisa la retroalimentación y registra tu mejora.':'Un diagnóstico breve te ayudará a elegir el acompañamiento para tu proyecto.'}</p><button class="accent" data-page="${state.user.diagnosis?'investigacion':'ruta'}" ${state.user.diagnosis&&next?`data-activity="${next.id}"`:''}>${state.user.diagnosis?'Continuar mi investigación →':'Iniciar diagnóstico →'}</button></div><div class="grid"><div class="card"><div class="label">PROGRESO DE MISIONES</div><div class="stat">${progress()}<small>%</small></div><progress value="${progress()}" max="100"></progress><small class="muted">${project.rewards.length} de ${state.activities.length} misiones con criterios internos</small></div><div class="card"><div class="label">EXPERIENCIA ACUMULADA</div><div class="stat">${xp()} <small>XP</small></div><small class="muted">100 XP por misión completada · Sin premios duplicados</small></div><div class="card"><div class="label">BIBLIOTECA PERSONAL</div><div class="stat">${project.sources.length}</div><small class="muted">Fuentes vinculadas a este proyecto</small></div></div><h2 class="section-title">Tu mesa de trabajo</h2><div class="grid">${[['investigacion','◎','Construye tu proyecto','Del problema a la metodología.',''],['lectura','▧','Lee con propósito','Analiza evidencia y limitaciones.','purple'],['biblioteca','▥','Organiza tus fuentes','Biblioteca y referencias académicas.','green'],['mentor','✧','Encuentra orientación','Preguntas para mejorar tu propuesta.','warm'],['portafolio','▣','Mira tu evolución','Evidencias y versiones anteriores.','green'],['exportar','↓','Comparte tus avances','Word, Markdown y vista imprimible.','']].map(([id,icon,title,desc,color])=>`<div class="card"><div class="icon ${color}">${icon}</div><h3>${title}</h3><p class="muted">${desc}</p><button class="secondary" data-page="${id}">Abrir →</button></div>`).join('')}</div>`}
function route(){const d=state.user.diagnosis;return header('Tu ruta de aprendizaje','Aprender haciendo, con evidencia en cada etapa.')+`<div class="cols"><section><div class="card"><h2>Diagnóstico inicial</h2><p class="muted">Cinco preguntas para orientar el acompañamiento. Puedes repetirlo.</p>${d?`<div class="guide"><strong>${esc(d.route)} · ${d.score}/${d.total}</strong><br>${esc(d.note)}</div>`:''}<form id="diagnosis">${state.questions.map((q,i)=>`<fieldset><legend>${i+1}. ${esc(q.text)}</legend>${q.options.map((o,j)=>`<label class="check"><input type="radio" name="q${i}" value="${j}" required>${esc(o)}</label>`).join('')}</fieldset>`).join('')}<button class="accent">Obtener mi ruta</button></form></div></section><section class="card"><h2>Un camino con propósito</h2><p class="muted">Finalización: seis misiones con evidencia, revisión y reflexión. El diagnóstico recomienda acompañamiento, sin certificar competencias.</p>${state.activities.map((a,i)=>`<div class="row mission"><div class="number">${i+1}</div><div><h3>${esc(a.title)}</h3><small class="muted">${i===0?'Empieza aquí':'Después de la misión '+i}</small></div><span>${project?.rewards.some(r=>r.activity===a.id)?'✓':'○'}</span></div>`).join('')}</section></div>`}
function editor(){const a=state.activities.find(a=>a.id===active)||state.activities[0],v=latest(a.id);let draft=null;try{draft=JSON.parse(localStorage.getItem(draftKey(a.id)))}catch{}const fields=draft?.fields||v?.data||{};return header('Mi investigación','Ideas que se convierten en una propuesta verificable.')+`<div class="tabs">${state.activities.map(a=>`<button class="${a.id===active?'active':'secondary'}" data-activity="${a.id}">${esc(a.title)}</button>`).join('')}</div><div class="cols"><section class="card"><div class="row"><h2>${esc(a.title)}</h2><span class="pill">${esc(v?.status||'Disponible')} · v${v?.revision||0}</span></div><div class="guide"><strong>Guía de trabajo</strong><p>${esc(a.guide)}</p><small><strong>Ejemplo orientador:</strong> ${esc(a.example)}</small></div>${draft?'<p class="notice">Borrador recuperado de este navegador. Al guardar se verifica que no exista una versión más reciente.</p>':''}<form id="evidence" data-base="${draft?.baseRevision??v?.revision??0}">${a.fields.map(f=>field(f,fields[f]||'')).join('')}<p class="muted"><small id="draft-status">El borrador se conserva en este navegador al escribir.</small></p><div class="actions"><button class="secondary" name="mode" value="save">Guardar versión</button><button class="accent" name="mode" value="review">Guardar y recibir feedback</button><button type="button" class="secondary" data-do="discard">Descartar borrador local</button></div></form></section><section><div class="card"><h2>Retroalimentación formativa</h2>${feedbackPanel(v)}</div><div class="card"><h3>Historial de esta actividad</h3>${project.versions.filter(v=>v.activity===active).map(v=>`<details><summary>Versión ${v.revision} · ${esc(v.status)} · ${new Date(v.created).toLocaleDateString('es-EC')}</summary>${Object.entries(v.data).map(([k,t])=>`<p><strong>${esc(k)}</strong><br>${esc(t)}</p>`).join('')}${v.feedback?`<p>${esc(v.feedback.origin)}</p>`:''}</details>`).join('')||'<p class="muted">Tu primera versión aparecerá aquí.</p>'}</div></section></div>`}
function feedbackPanel(v){const fb=v?.feedback;if(!fb)return '<p class="muted">Completa tu propuesta y pide feedback. La rúbrica revisa que cada apartado esté desarrollado con contenido propio y las reglas básicas de la misión; no evalúa la validez científica.</p>';const v2=fb.version===2,pending=fb.criteria.filter(c=>!c.met),done=fb.score===100;return `<span class="pill ${done?'done':''}">${fb.score}/100 · Requisitos de la rúbrica</span><p class="muted"><small>${esc(fb.origin)}</small></p><ul class="rubric">${fb.criteria.map(c=>`<li class="${c.met?'met':'unmet'}"><span aria-hidden="true">${c.met?'✓':'○'}</span><div><strong>${esc(c.criterion)}</strong><br><small>${esc(v2?c.detail:(c.met?'Desarrollado':'Mínimo orientador: 20 caracteres'))}</small></div></li>`).join('')}</ul>${v2&&fb.advice.length?`<div class="guide"><strong>Recomendaciones</strong> <small class="muted">(no bloquean el avance)</small>${fb.advice.map(a=>`<p>${esc(a.text)}</p>`).join('')}</div>`:''}${!v2?`<div class="guide">${fb.suggestions.map(s=>`<p>${esc(s)}</p>`).join('')}</div>`:''}${done?`<form id="complete">${field('Mejora aplicada o justificación de conservación',v.reflection||'')}<label class="check"><input type="checkbox" required>He revisado el feedback y contrastado mi propuesta.</label><button>Registrar revisión y completar misión</button></form>`:`<p class="notice">${pending.length===1?'Queda 1 requisito pendiente':'Quedan '+pending.length+' requisitos pendientes'}. Corrígelos en el formulario y pulsa <strong>Guardar y recibir feedback</strong> para completar la misión.</p>`}`}
function library(){return header('Biblioteca y citas','Conserva las fuentes que sostienen tus ideas.')+`<div class="cols"><section class="card">${(()=>{const e=project.sources.find(s=>s.id===editSource)||{};const val=k=>`value="${esc(e[k]||'')}"`;return `<h2>${e.id?'Editar fuente':'Registrar una fuente'}</h2>${e.id?'<p class="notice">Estás corrigiendo una fuente ya registrada. Su ficha de lectura se conserva.</p>':''}<div class="guide">Copia los metadatos desde la publicación original. Para buscar literatura, abre un buscador académico y verifica cada resultado antes de registrarlo.</div><div class="actions"><a href="https://search.crossref.org/" target="_blank" rel="noopener noreferrer">Buscar en Crossref ↗</a><a href="https://scholar.google.com/" target="_blank" rel="noopener noreferrer">Google Scholar ↗</a></div><form id="source"><label>Autoría normalizada<input name="author" placeholder="Apellido, N." required ${val('author')}></label><label>Año<input name="year" pattern="[0-9]{4}" placeholder="2026" required ${val('year')}></label><label>Título<input name="title" required ${val('title')}></label><label>Revista o editorial<input name="venue" required ${val('venue')}></label><label>DOI / URL<input name="url" type="url" placeholder="https://doi.org/…" ${val('url')}></label><div class="actions"><button class="accent">${e.id?'Guardar cambios':'＋ Agregar referencia'}</button>${e.id?'<button type="button" class="secondary" data-do="cancel-edit">Cancelar edición</button>':''}</div></form>`})()}</section><section class="card"><div class="row"><h2>Fuentes guardadas</h2><span class="pill">${project.sources.length}</span></div><label>Filtrar biblioteca<input id="filter" type="search" placeholder="Título, autor o año"></label><label>Estilo de referencia<select id="citation-style"><option>APA</option><option>IEEE</option><option>Vancouver</option></select></label><p class="muted"><small>Plantillas básicas: APA 7, IEEE y Vancouver. Revisa autoría, volumen, páginas y tipo documental en el manual institucional.</small></p><div id="sources">${sourceList('','APA')}</div></section></div>`}
function reference(s,style){const {author:a,year:y,title:t,venue:v,url:u=''}=s;if(style==='IEEE')return `${a}, “${t},” ${v}, ${y}. ${u}`;if(style==='Vancouver')return `${a}. ${t}. ${v}. ${y}. ${u}`;return `${a} (${y}). ${t}. ${v}. ${u}`}
function sourceList(q,style){return project.sources.filter(s=>JSON.stringify(s).toLowerCase().includes(q.toLowerCase())).map(s=>`<article class="source"><h3>${esc(s.title)}</h3><p>${esc(reference(s,style))}</p>${s.url?`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">Consultar fuente ↗</a>`:''}<div class="actions"><button class="secondary" data-read="${s.id}">${project.readings[s.id]?'Revisar ficha':'Crear ficha'}</button>${project.owner?`<button class="secondary" data-edit-source="${s.id}">Editar</button><button class="danger" data-del-source="${s.id}">Eliminar</button>`:''}</div></article>`).join('')||'<p class="muted">No hay fuentes que mostrar.</p>'}
function reading(){if(!project.sources.length)return header('Lectura crítica','De la lectura a la evidencia.')+`<div class="card empty"><h2>Primero registra una fuente</h2><p>Las fichas se vinculan a una publicación de tu biblioteca.</p><button data-page="biblioteca">Ir a biblioteca</button></div>`;if(!project.sources.some(s=>s.id===sourceId))sourceId=project.sources[0].id;const values=project.readings[sourceId]||{};return header('Lectura crítica','Distingue los hallazgos del artículo de tu interpretación.')+`<div class="cols"><section class="card"><label>Artículo seleccionado<select id="reading-source">${project.sources.map(s=>`<option value="${s.id}" ${s.id===sourceId?'selected':''}>${esc(s.title)}</option>`).join('')}</select></label><div class="guide">Resume con tus palabras. Separa resultados reportados y análisis propio. Si incluyes una cita literal, registra su página o localizador.</div><form id="reading">${state.readingFields.map(f=>field(f,values[f]||'')).join('')}<div class="actions"><button class="accent">Guardar ficha de lectura</button>${project.readings[sourceId]&&project.owner?'<button type="button" class="danger" data-do="delete-reading">Eliminar ficha</button>':''}</div></form></section><section class="card"><h2>Matriz de evidencia</h2><p class="muted">Organiza la relación entre fuentes, resultados y tu investigación.</p>${project.sources.map(s=>`<div class="source"><h3>${esc(s.title)}</h3><span class="pill">${project.readings[s.id]?'Ficha guardada':'Pendiente'}</span><p><strong>Hallazgos:</strong> ${esc(project.readings[s.id]?.Resultados||'Sin registrar')}</p><p><strong>Aporte:</strong> ${esc(project.readings[s.id]?.['Relación con mi tema']||'Sin registrar')}</p></div>`).join('')}</section></div>`}
function mentor(){return header('Un espacio para pensar mejor','Orientación metodológica con decisiones en tus manos.')+`<div class="notice">${CLOUD?'Orientación por reglas pedagógicas en el servidor de InvestigaApp, sin IA generativa. Tus textos no se envían a proveedores de IA.':'Modo local: respuestas por reglas, sin conexión a una IA generativa. No se envían tus textos a proveedores externos.'} Las sugerencias requieren revisión humana.</div><div class="card"><div class="chat" id="chat"><div class="bubble"><strong>✧ Orientador metodológico</strong><br>Cuéntame tu duda y elige la misión en la que estás trabajando. Revisaré lo que ya escribiste y te propondré preguntas para mejorar tu propuesta; las decisiones son tuyas.</div>${project.messages.map(m=>`<div class="bubble mine">${esc(m.question)}</div><div class="bubble">${esc(m.answer)}</div>`).join('')}</div><form id="mentor"><div class="chips" aria-label="Consultas frecuentes">${[["tema","¿Cómo delimito mi tema?"],["problema","¿Mi pregunta de investigación está bien formulada?"],["objetivos","¿Cómo redacto mis objetivos?"],["marco","¿Dónde busco fuentes confiables y cómo las cito?"],["metodologia","¿Qué enfoque metodológico me conviene?"],["plan","¿Cómo organizo mi cronograma?"]].map(([a,q])=>`<button type="button" class="chip" data-ask="${esc(q)}" data-ask-activity="${a}">${esc(q)}</button>`).join("")}</div><label>Misión sobre la que consultas<select name="activity" id="mentor-activity">${state.activities.map(a=>`<option value="${a.id}" ${a.id===active?"selected":""}>${esc(a.title)}</option>`).join("")}</select></label><label>Tu consulta<textarea name="question" required minlength="10" maxlength="6000" placeholder="¿Cómo puedo delimitar mi pregunta de investigación?"></textarea></label><button class="accent">Solicitar orientación →</button></form></div>`}
function portfolio(){return header('Tu portafolio investigativo','Cada versión cuenta una parte de tu proceso.','<button data-page="exportar">Exportar avances ↓</button>')+`<div class="cols"><section class="card"><h2>${esc(project.project.title)}</h2><div class="stat">${progress()}%</div><progress max="100" value="${progress()}"></progress><p class="muted">${project.rewards.length} de ${state.activities.length} misiones completadas.</p>${state.activities.map(a=>{const v=latest(a.id);return `<div class="mission"><div class="row"><h3>${esc(a.title)}</h3><span class="pill ${project.rewards.some(r=>r.activity===a.id)?'done':''}">${esc(v?.status||'Sin evidencia')}</span></div><small class="muted">${v?'Versión '+v.revision:'Comienza una primera versión'}</small><div class="actions"><button class="secondary" data-activity="${a.id}">Abrir evidencia</button></div></div>`}).join('')}</section><section><div class="card"><h2>Logros con evidencia</h2><div class="stat">${xp()} XP</div>${project.rewards.map(r=>`<div class="source"><span class="icon warm">✦</span><h3>${esc(state.activities.find(a=>a.id===r.activity).title)}</h3><small>100 XP · Evidencia revisada y reflexión registrada. Reconocimiento interno.</small></div>`).join('')||'<p class="muted">Completa tu primera misión para obtener un reconocimiento.</p>'}</div><div class="card"><h2>Versiones conservadas</h2><p>${project.versions.length} versiones · ${project.sources.length} fuentes · ${Object.keys(project.readings).length} fichas</p><p class="muted">Las versiones anteriores permanecen disponibles en cada actividad y en la exportación del historial.</p></div>${project.owner?`<div class="card"><h2>Gestionar proyecto</h2><form id="rename"><label>Título del proyecto<input name="title" required maxlength="200" value="${esc(project.project.title)}"></label><button class="secondary">Cambiar título</button></form><h3>Eliminar proyecto</h3><p class="muted"><small>Borra para siempre sus versiones, fuentes, fichas, consultas y comentarios. Exporta antes el historial si quieres conservarlo.</small></p><button class="danger" data-do="delete-project">Eliminar este proyecto</button></div>`:''}</section></div>`}
function preview(){return `<h1>${esc(project.project.title)}</h1><p>${esc(state.user.name)} · InvestigaApp · ${new Date().toLocaleDateString('es-EC')}</p>${state.activities.map(a=>{const v=latest(a.id);return v?`<section><h2>${esc(a.title)} · v${v.revision}</h2><p>Estado: ${esc(v.status)} · ${esc(v.created)}</p>${Object.entries(v.data).map(([k,t])=>`<h3>${esc(k)}</h3><p>${esc(t)}</p>`).join('')}<p>Reflexión: ${esc(v.reflection)}</p></section>`:''}).join('')}<h2>Referencias · APA (básico)</h2>${project.sources.map(s=>`<p>${esc(reference(s,'APA'))}</p>`).join('')}<h2>Fichas críticas</h2>${project.sources.filter(s=>project.readings[s.id]).map(s=>`<h3>${esc(s.title)}</h3>${Object.entries(project.readings[s.id]).map(([k,v])=>`<p><strong>${esc(k)}:</strong> ${esc(v)}</p>`).join('')}`).join('')}<h2>Trazabilidad de versiones</h2>${project.versions.map(v=>`<p>${esc(v.activity)} · v${v.revision} · ${esc(v.created)} · ${esc(v.status)}<br>${esc(v.feedback?.suggestions.join(' ')||'Sin evaluación en esta versión')}</p>`).join('')}`}
function exports(){return header('Tus avances, listos para compartir','Revisa el documento antes de descargarlo.')+`<div class="card no-print"><h2>Exportación académica</h2><label>Estilo de referencias en Word y Markdown<select id="export-style"><option>APA</option><option>IEEE</option><option>Vancouver</option></select></label><div class="actions"><button class="accent" data-export="docx">↓ Word (.docx)</button><button class="secondary" data-export="md">↓ Markdown</button><button class="secondary" data-export="json">↓ Historial JSON</button><button data-do="print">Imprimir / Guardar como PDF</button></div><p class="muted"><small>Word y Markdown contienen los últimos textos, las fichas y un registro de versiones y feedback. JSON conserva el texto íntegro de todas las versiones. La impresión usa APA básico y el diálogo del navegador.</small></p></div><article class="card preview">${project.versions.length?preview():'Todavía no hay evidencias. Guarda tu primera versión para exportar.'}</article>`}
function reviews(){return header('Revisión docente','Comentarios vinculados a una versión concreta, con acceso revocable.',state.user.role==='docente'?'<button class="secondary" data-page="docente">← Panel docente</button>':'')+`<div class="cols"><section><div class="card"><h2>Permisos del proyecto</h2>${project.owner?`<p class="muted">Autoriza la consulta del portafolio y la creación de comentarios. El docente no podrá modificar tus evidencias.</p>${WEB?'<p class="notice">En la edición web, la cuenta docente debe estar registrada en este mismo navegador (por ejemplo, un equipo de aula o laboratorio). Para revisar desde otro equipo, exporta el portafolio y compártelo.</p>':''}<form id="membership"><label>Correo del docente<input type="email" name="email" required></label><label>Operación<select name="operation"><option value="grant">Autorizar consulta y comentarios</option><option value="revoke">Revocar acceso</option></select></label><button>Actualizar permiso</button></form><h3>Docentes autorizados</h3>${project.members.map(m=>`<p>${esc(m.name)} · ${esc(m.email)}</p>`).join('')||'<p class="muted">Ningún docente autorizado.</p>'}`:'<p class="guide">Proyecto compartido: consulta y comentarios. Las evidencias son editables únicamente por su propietario.</p>'}</div><div class="card"><h2>Comentar una evidencia</h2>${project.versions.length?`<form id="comment"><label>Versión<select name="version">${project.versions.map(v=>`<option value="${v.id}">${esc(activityTitle(v.activity))} · v${v.revision} · ${esc(v.status)}${project.comments.some(c=>c.activity===v.activity&&c.revision===v.revision)?'':' · sin comentarios'}</option>`).join('')}</select></label><label>Retroalimentación docente<textarea name="text" required minlength="15"></textarea></label><button class="accent">Guardar comentario</button></form>`:'<p>Primero guarda una evidencia del proyecto.</p>'}</div></section><section class="card"><h2>Historial de revisión</h2>${project.comments.map(c=>`<article class="source"><strong>${esc(c.name)}</strong><p class="muted">${esc(activityTitle(c.activity))} · v${c.revision} · ${new Date(c.created).toLocaleString('es-EC')}</p><p>${esc(c.text)}</p></article>`).join('')||'<p class="muted">Los comentarios aparecerán aquí.</p>'}</section></div>`}
function contents(){return header('Contenidos metodológicos','Guías y ejemplos para acompañar cada actividad.')+`<div class="card">${state.user.role==='administrador'?`<h2>Publicar una nueva versión</h2><p class="muted">La publicación actualiza la guía de trabajo. Conserva las versiones anteriores de contenidos y las evaluaciones registradas.</p><form id="contents"><label>Actividad<select name="activity">${state.activities.map(a=>`<option value="${a.id}">${esc(a.title)}</option>`).join('')}</select></label><label>Guía<textarea name="guide" minlength="30" required></textarea></label><label>Ejemplo aplicado<textarea name="example" minlength="20" required></textarea></label><button class="accent">Publicar contenido</button></form>`:(WEB?'<p class="guide">La edición de contenidos está reservada a una cuenta administradora. En la edición web, el rol se elige en Mi perfil y solo afecta a este navegador.</p>':CLOUD?'<p class="guide">La edición de contenidos está reservada a la cuenta administradora de la plataforma.</p>':'<p class="guide">La edición de contenidos está reservada a una cuenta administradora configurada localmente.</p>')}</div>${state.activities.map(a=>`<div class="card"><h2>${esc(a.title)} <small class="muted">· contenido ${a.contentVersion||'base'}</small></h2><p>${esc(a.guide)}</p><div class="guide">${esc(a.example)}</div></div>`).join('')}`}
function profile(){const p=state.user.profile||{};return header('Mi perfil académico','Ajusta tu contexto y tus preferencias.')+`<div class="card"><h2>${esc(state.user.name)}</h2><p class="muted">${esc(state.user.email)} · ${esc(state.user.role)}</p><form id="profile">${field('Institución',p['Institución']||'','text')}${field('Área de estudio',p['Área de estudio']||'','text')}${field('Meta de investigación',p['Meta de investigación']||'')}${WEB?`<label>Rol en este navegador<select name="role">${['estudiante','docente','administrador'].map(r=>`<option value="${r}" ${state.user.role===r?'selected':''}>${r[0].toUpperCase()+r.slice(1)}</option>`).join('')}</select></label>`:''}<label class="check"><input type="checkbox" name="reminders" ${p.reminders?'checked':''}>Mostrar recordatorio de revisión al entrar</label><button>Guardar perfil</button></form></div>${CLOUD&&state.user.role==='administrador'?`<div class="card"><h2>Asignar roles</h2><p class="muted">Cada persona debe registrarse primero. Asigna el rol docente a quienes revisarán proyectos.</p><form id="role"><label>Correo de la cuenta<input type="email" name="email" required></label><label>Rol<select name="role"><option value="docente">Docente</option><option value="estudiante">Estudiante</option><option value="administrador">Administrador</option></select></label><button>Asignar rol</button></form></div>`:''}${security()}${CLOUD?`<div class="card"><h2>Mis datos</h2><p class="muted">Tu cuenta, tus proyectos y tu historial se guardan en la plataforma y quedan disponibles desde cualquier equipo. Puedes descargar una copia completa cuando quieras.</p><div class="actions"><button class="accent" data-do="backup">↓ Descargar mis datos (.json)</button></div></div>`:''}${WEB?`<div class="card"><h2>Respaldo de tus datos</h2><p class="muted">Todo se guarda en el almacenamiento de este navegador. Si borras los datos de navegación, cambias de equipo o de navegador, perderás el acceso. Descarga un respaldo con frecuencia.</p><div class="actions"><button class="accent" data-do="backup">↓ Descargar respaldo (.json)</button><label class="file-btn">Restaurar respaldo<input type="file" id="restore" accept="application/json,.json"></label></div><p class="muted"><small>Restaurar reemplaza todas las cuentas y proyectos de este navegador por los del archivo y cierra la sesión.</small></p></div>`:''}<div class="notice">${CLOUD?'Edición en la nube: cada cambio queda registrado con fecha para garantizar la trazabilidad de tu proceso.':WEB?'Edición web: no hay servidor ni base de datos en la nube; los datos no salen de este navegador.':'Los datos se almacenan en SQLite en este equipo.'} Esta edición no publica rankings. Solo los docentes autorizados por el propietario pueden consultar un portafolio. Los borradores de actividades permanecen en el navegador hasta guardarlos o descartarlos.</div>`}
/* Panel docente: proyectos compartidos con la cuenta docente */
let teacherData=null,teacherFilter='',teacherSort='unreviewed';
const daysSince=iso=>Math.max(0,Math.floor((Date.now()-new Date(iso))/864e5));
const IDLE_DAYS=14;
function missionLabel(m){const s=m.completed?'misión completada':m.status==='Retroalimentada'?`con feedback (${m.score}/100)`:m.status==='En progreso'?'versión guardada sin feedback':m.status?m.status.toLowerCase():'sin evidencia';return `${m.title}: ${s}${m.revision?` · v${m.revision}`:''}${m.revision&&!m.commented?' · sin tu comentario':''}`}
function missionDots(r){return `<div class="dots">${r.missions.map((m,i)=>{const cls=m.completed?'done':m.status==='Retroalimentada'?'fb':m.status?'prog':'none';return `<span class="dot ${cls}${m.revision&&!m.commented?' pending':''}" title="${esc(missionLabel(m))}"><span aria-hidden="true">${m.completed?'✓':i+1}</span><span class="sr-only">${esc(missionLabel(m))}.</span></span>`}).join('')}</div>`}
function teacherRows(){const q=teacherFilter.trim().toLowerCase();const by={unreviewed:(a,b)=>b.unreviewed-a.unreviewed||b.lastActivity.localeCompare(a.lastActivity),recent:(a,b)=>b.lastActivity.localeCompare(a.lastActivity),idle:(a,b)=>a.lastActivity.localeCompare(b.lastActivity),progress:(a,b)=>a.completed-b.completed||a.ownerName.localeCompare(b.ownerName),name:(a,b)=>a.ownerName.localeCompare(b.ownerName,'es')};return teacherData.projects.filter(r=>(r.ownerName+' '+r.ownerEmail+' '+r.title).toLowerCase().includes(q)).sort(by[teacherSort])}
function teacherTable(){const rows=teacherRows(),n=state.activities.length;if(!rows.length)return '<p class="muted">Ningún proyecto coincide con el filtro.</p>';return `<div class="table-wrap"><table class="teacher"><thead><tr><th scope="col">Estudiante</th><th scope="col">Proyecto</th><th scope="col">Misiones</th><th scope="col">Avance</th><th scope="col">Última actividad</th><th scope="col">Por comentar</th><th scope="col"><span class="sr-only">Acciones</span></th></tr></thead><tbody>${rows.map(r=>{const d=daysSince(r.lastActivity);return `<tr><td><strong>${esc(r.ownerName)}</strong><br><small class="muted">${esc(r.ownerEmail)}</small></td><td>${esc(r.title)}<br><small class="muted">${r.nextMission?'Siguiente: '+esc(r.nextMission):'Ruta completa'}</small></td><td>${missionDots(r)}</td><td><strong>${r.completed}/${n}</strong><progress max="${n}" value="${r.completed}"></progress><small class="muted">${r.sources} fuentes · ${r.readings} fichas</small></td><td>${new Date(r.lastActivity).toLocaleDateString('es-EC')}<br><small class="${d>=IDLE_DAYS?'idle':'muted'}">${d===0?'hoy':d===1?'hace 1 día':'hace '+d+' días'}${d>=IDLE_DAYS?' · sin actividad':''}</small></td><td>${r.unreviewed?`<span class="pill warn">${r.unreviewed} ${r.unreviewed===1?'evidencia':'evidencias'}</span>`:'<span class="pill done">Al día</span>'}</td><td><button class="secondary" data-review="${esc(r.projectId)}">Revisar →</button></td></tr>`}).join('')}</tbody></table></div><p class="muted legend"><small><span class="dot done">✓</span> completada <span class="dot fb">2</span> con feedback <span class="dot prog">3</span> guardada sin feedback <span class="dot none">4</span> sin evidencia <span class="dot fb pending">5</span> con borde naranja: última versión sin tu comentario</small></p>`}
function teacherPanel(){const head=header('Panel docente','Avance de los proyectos que tus estudiantes compartieron contigo.','<div class="actions"><button class="secondary" data-do="teacher-refresh">Actualizar</button>'+(teacherData?.projects.length?'<button class="secondary" data-do="teacher-csv">↓ Descargar CSV</button>':'')+'</div>');
 if(!teacherData)return head+'<div class="card"><p class="muted">Cargando proyectos…</p></div>';
 const rows=teacherData.projects;
 if(!rows.length)return head+`<div class="card empty"><div class="icon">◫</div><h2>Aún no hay proyectos compartidos</h2><p class="muted">Pide a tus estudiantes que abran <strong>Revisión docente</strong> en su proyecto y autoricen tu correo: <strong>${esc(state.user.email)}</strong>.${WEB?' En la edición web, ambas cuentas deben estar en este mismo navegador.':''}</p></div>`;
 const n=state.activities.length,avg=Math.round(rows.reduce((s,r)=>s+r.completed,0)/rows.length/n*100),pending=rows.reduce((s,r)=>s+r.unreviewed,0),idle=rows.filter(r=>daysSince(r.lastActivity)>=IDLE_DAYS).length,done=rows.filter(r=>r.completed===n).length;
 return head+`<div class="grid four"><div class="card"><div class="label">PROYECTOS COMPARTIDOS</div><div class="stat">${rows.length}</div><small class="muted">${done} con la ruta completa</small></div><div class="card"><div class="label">AVANCE PROMEDIO</div><div class="stat">${avg}<small>%</small></div><progress value="${avg}" max="100"></progress></div><div class="card"><div class="label">EVIDENCIAS POR COMENTAR</div><div class="stat">${pending}</div><small class="muted">Últimas versiones sin tu comentario</small></div><div class="card"><div class="label">SIN ACTIVIDAD</div><div class="stat">${idle}</div><small class="muted">Proyectos sin cambios en ${IDLE_DAYS} días o más</small></div></div><div class="card"><div class="row filters"><label>Buscar<input id="teacher-filter" type="search" placeholder="Estudiante, correo o proyecto" value="${esc(teacherFilter)}"></label><label>Ordenar por<select id="teacher-sort">${[['unreviewed','Más evidencias por comentar'],['recent','Actividad más reciente'],['idle','Más tiempo sin actividad'],['progress','Menor avance primero'],['name','Nombre']].map(([v,l])=>`<option value="${v}" ${teacherSort===v?'selected':''}>${l}</option>`).join('')}</select></label></div><div id="teacher-table">${teacherTable()}</div></div>`}
function bindTeacher(){
 if(page==='docente'&&!teacherData)run(async()=>{teacherData=await api('teacher');render()});
 const bindReview=()=>document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>run(async()=>{project=await api('projects/'+b.dataset.review);sessionStorage.setItem('project',b.dataset.review);page='revision';render();window.scrollTo(0,0)}));
 bindReview();
 const redraw=()=>{$('#teacher-table').innerHTML=teacherTable();bindReview()};
 if($('#teacher-filter'))$('#teacher-filter').oninput=e=>{teacherFilter=e.target.value;redraw()};
 if($('#teacher-sort'))$('#teacher-sort').onchange=e=>{teacherSort=e.target.value;redraw()};}
function teacherCsv(){const q=v=>'"'+String(v??'').replace(/"/g,'""')+'"',status=m=>m.completed?'Completada':m.status||'Sin evidencia';
 const head=['Estudiante','Correo','Proyecto','Misiones completadas','XP','Fuentes','Fichas','Versiones','Evidencias por comentar','Última actividad',...state.activities.map(a=>a.title)];
 const lines=[head,...teacherRows().map(r=>[r.ownerName,r.ownerEmail,r.title,r.completed,r.xp,r.sources,r.readings,r.versions,r.unreviewed,r.lastActivity.slice(0,10),...r.missions.map(status)])].map(row=>row.map(q).join(';'));
 const url=URL.createObjectURL(new Blob([String.fromCharCode(0xFEFF)+lines.join(String.fromCharCode(13,10))],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='InvestigaApp-panel-docente-'+new Date().toISOString().slice(0,10)+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function bind(){if(project&&!project.owner){document.querySelectorAll('#evidence button,#complete button,#source button,#reading button,#mentor button,[data-export]').forEach(b=>b.disabled=true);}document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;if(page==='docente')teacherData=null;render();window.scrollTo(0,0)});document.querySelectorAll('[data-activity]').forEach(b=>b.onclick=()=>{active=b.dataset.activity;page='investigacion';render()});bindSources();document.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>run(async()=>{const r=await projectApi('export',{format:b.dataset.export,style:$('#export-style').value});const url=URL.createObjectURL(await r.blob());const a=document.createElement('a');a.href=url;a.download='InvestigaApp-portafolio.'+b.dataset.export;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}));document.querySelectorAll('[data-do]').forEach(b=>b.onclick=()=>run(async()=>{switch(b.dataset.do){case 'new':{const title=prompt('Título de tu nuevo proyecto');if(!title?.trim())return;const p=await api('projects',{title});project=null;sessionStorage.setItem('project',p.id);page='inicio';await reload();render();break}case 'logout':await api('logout',{});state=null;project=null;teacherData=null;clearToast();sessionStorage.removeItem('project');auth();break;case 'print':if(!project.versions.length)throw new Error('Guarda una evidencia primero.');window.print();break;case 'discard':localStorage.removeItem(draftKey(active));render();break;case 'teacher-refresh':teacherData=null;render();break;case 'teacher-csv':teacherCsv();break;case 'cancel-edit':editSource='';render();break;case 'delete-reading':{if(!confirm('¿Eliminar la ficha de lectura de esta fuente? La fuente se conserva.'))return;await projectApi('reading-delete',{sourceId});await reload();render();toast('Ficha eliminada.');break}case 'delete-project':{const t=prompt('Esta acción borra el proyecto y todo su historial y no se puede deshacer.\nPara confirmar, escribe el título exacto:\n'+project.project.title);if(t===null)return;await projectApi('delete',{confirm:t.trim()});project=null;sessionStorage.removeItem('project');page='inicio';await reload();render();toast('Proyecto eliminado.');break}case 'backup':{const url=URL.createObjectURL(await BACKEND.backup());const a=document.createElement('a');a.href=url;a.download='InvestigaApp-'+(CLOUD?'mis-datos-':'respaldo-')+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Respaldo descargado. Guárdalo en un lugar privado.');break}}}));$('#project-select').onchange=e=>run(async()=>{if(!e.target.value)return;editSource='';project=await api('projects/'+e.target.value);sessionStorage.setItem('project',e.target.value);render()});
 bindForm('membership',async f=>{await projectApi('members',{email:f.get('email'),revoke:f.get('operation')==='revoke'});await reload();render();toast('Permiso actualizado.');});
 bindForm('comment',async f=>{const v=project.versions.find(v=>v.id===Number(f.get('version')));await projectApi('comments',{activity:v.activity,revision:v.revision,text:f.get('text')});await reload();render();toast('Comentario guardado.');});
 bindForm('contents',async f=>{await api('contents',Object.fromEntries(f));await reload();render();toast('Contenido publicado como nueva versión.');});
 bindForm('diagnosis',async f=>{await api('diagnosis',{answers:state.questions.map((q,i)=>Number(f.get('q'+i)))});await reload();render();toast('Diagnóstico completado. Tu ruta está disponible.')});
 bindForm('evidence',async(f,e)=>{const fields=Object.fromEntries(f);const baseRevision=Number(e.target.dataset.base);await projectApi('evidence',{activity:active,fields,baseRevision,review:e.submitter?.value==='review'});localStorage.removeItem(draftKey(active));await reload();render();toast('Nueva versión guardada.');});
 if($('#evidence'))$('#evidence').oninput=e=>{try{localStorage.setItem(draftKey(active),JSON.stringify({fields:Object.fromEntries(new FormData(e.currentTarget)),baseRevision:Number(e.currentTarget.dataset.base)}));$('#draft-status').textContent='Borrador local guardado · '+new Date().toLocaleTimeString('es-EC')}catch{$('#draft-status').textContent='No se pudo guardar el borrador local. Guarda una versión '+(WEB?'ahora.':'en el servidor.')}};
 bindForm('complete',async f=>{await projectApi('complete',{activity:active,reflection:f.get('Mejora aplicada o justificación de conservación')});await reload();render();toast('Revisión registrada. La recompensa se asigna una sola vez.');});
 bindForm('source',async f=>{const data=Object.fromEntries(f);if(editSource)await projectApi('source-update',{...data,sourceId:editSource});else await projectApi('sources',data);const edited=!!editSource;editSource='';await reload();render();toast(edited?'Fuente actualizada.':'Fuente registrada.');});
 bindForm('reading',async f=>{await projectApi('reading',{sourceId,fields:Object.fromEntries(f)});await reload();render();toast('Ficha guardada.');});
 document.querySelectorAll('[data-ask]').forEach(b=>b.onclick=()=>{$('#mentor textarea').value=b.dataset.ask;$('#mentor-activity').value=b.dataset.askActivity;$('#mentor textarea').focus()});
 bindForm('mentor',async f=>{active=f.get('activity');await projectApi('mentor',{question:f.get('question'),activity:f.get('activity')});await reload();render();$('#chat').scrollTop=$('#chat').scrollHeight;});
 bindForm('rename',async f=>{await projectApi('rename',{title:f.get('title')});await reload();render();toast('Título actualizado.');});
 bindForm('password',async(f,e)=>{if(f.get('password')!==f.get('confirm'))throw new Error('Las contraseñas nuevas no coinciden.');const r=await api('password',{current:f.get('current'),password:f.get('password')});e.target.reset();toast('Contraseña cambiada.'+(r.closedSessions?' Se cerraron '+r.closedSessions+' sesión(es) en otros navegadores.':''))});
 bindForm('recovery',async(f,e)=>{const r=await api('recovery-code',{current:f.get('current')});e.target.reset();await reload();showRecoveryCode(r.recoveryCode,'Tu código anterior ya no funciona. Guarda este nuevo código.')});
 bindForm('role',async(f,e)=>{await api('role',{email:f.get('email'),role:f.get('role')});e.target.reset();toast('Rol asignado.');});
 bindForm('profile',async f=>{const p=Object.fromEntries(f);p.reminders=f.has('reminders');await api('profile',p);await reload();render();toast('Perfil actualizado.');});
 if($('#filter')){const filter=()=>{$('#sources').innerHTML=sourceList($('#filter').value,$('#citation-style').value);bindSources()};$('#filter').oninput=filter;$('#citation-style').onchange=filter;}
 if($('#restore'))$('#restore').onchange=e=>run(async()=>{const f=e.target.files[0];if(!f)return;if(!confirm('Se reemplazarán todas las cuentas y proyectos de este navegador por los del respaldo. ¿Continuar?')){e.target.value='';return}await BACKEND.restore(f);state=null;project=null;sessionStorage.removeItem('project');auth();toast('Respaldo restaurado. Inicia sesión.')});
 bindTeacher();
 if($('#reading-source'))$('#reading-source').onchange=e=>{sourceId=e.target.value;render()};}
function bindSources(){document.querySelectorAll('[data-read]').forEach(b=>b.onclick=()=>{sourceId=b.dataset.read;page='lectura';render()});document.querySelectorAll('[data-edit-source]').forEach(b=>b.onclick=()=>{editSource=b.dataset.editSource;render();$('#source input').focus()});document.querySelectorAll('[data-del-source]').forEach(b=>b.onclick=()=>run(async()=>{const s=project.sources.find(s=>s.id===b.dataset.delSource);if(!confirm('¿Eliminar «'+s.title+'»?'+(project.readings[s.id]?' También se borrará su ficha de lectura.':'')+' Esta acción no se puede deshacer.'))return;await projectApi('source-delete',{sourceId:s.id});if(editSource===s.id)editSource='';await reload();render();toast('Fuente eliminada.')}))}
async function run(fn){try{await fn()}catch(e){toast(e.message)}}
function bindForm(id,fn){const el=$('#'+id);if(el)el.onsubmit=e=>{e.preventDefault();run(async()=>{const b=e.submitter;if(b)b.disabled=true;try{await fn(new FormData(e.target),e)}finally{if(b)b.disabled=false}})}}
function start(){if(CLOUD&&BACKEND.recovery){authMode='newpass';auth();return}
 reload().then(()=>{if(state.user.role==='docente')page='docente';render();if(state.user.profile.reminders)toast('Recuerda revisar una evidencia y registrar tu mejora de hoy.')}).catch(e=>{if(e.message.includes('Inicia sesión'))auth();else{$('#app').innerHTML=CLOUD?'<div class="card"><h1>No se pudo abrir InvestigaApp</h1><p>'+esc(e.message)+'</p><p>Comprueba tu conexión a internet y vuelve a cargar esta página.</p></div>':WEB?'<div class="card"><h1>No se pudo abrir InvestigaApp</h1><p>'+esc(e.message)+'</p><p>Comprueba que el navegador permita el almacenamiento local (no uses modo privado estricto) y vuelve a cargar esta página.</p></div>':'<div class="card"><h1>No se pudo conectar</h1><p>'+esc(e.message)+'</p><p>Inicia el servidor y vuelve a cargar esta página.</p></div>'}});}
start();
